using System;using System.Diagnostics;using System.IO;using System.Text.Json;using MassiveArmy.Industrial;
class Benchmark {static void Main(string[] args){if(args.Length<1||args.Length>2){Console.WriteLine("Usage: IndustrialPowerBenchmark <output.json> [water]");return;}bool water=args.Length==2&&args[1]=="water";var world=new IndustrialWorld();for(int actor=1;actor<=16;actor++)world.Register(actor,new FramePose{body=1,y=10000,x=actor*.25});for(int i=0;i<1000;i++){string id=water?(i<100?"generator":i<200?"pump":i<300?"sluice":"store"):(i<100?"generator":i<400?"foundry":i<700?"press":"store");var machine=new IndustrialMachine{id=world.AllocateId(),owner=1,definition=id,recipe=IndustrialCatalog.Machines[id].recipe,pose=new FramePose{body=1,y=10000,x=(i%32)*6,z=(i/32)*6},input=new Inventory{capacity=1000000},output=new Inventory{capacity=1000000},powerSource=1+i%100};if(id=="generator")machine.input.Add("fuel",10000);if(id=="foundry")machine.input.Add("iron-ore",40000);if(id=="press")machine.input.Add("iron-bar",40000);if(water&&id=="pump"){machine.input.capacity=10000000;machine.input.Add("water",10000000);machine.waterTarget=201+i%100;}if(water&&id=="sluice"){machine.input.capacity=10000000;machine.output.capacity=10000000;machine.input.bulk=new MaterialLot{litres=10000000,iron=2000000};}world.machines.Add(machine);}for(int i=0;i<(water?6000:600);i++)world.Step();GC.Collect();GC.WaitForPendingFinalizers();var samples=new double[water?30000:3000];var elapsed=Stopwatch.StartNew();for(int i=0;i<samples.Length;i++){long start=Stopwatch.GetTimestamp();world.Step();samples[i]=Stopwatch.GetElapsedTime(start).TotalMilliseconds;}elapsed.Stop();Array.Sort(samples);var process=Process.GetCurrentProcess();var report=new {scope="Standalone .NET industrial-core comparison, 1000 identical machines and 16 observers. Not Unity frame/fog/GPU or fleet acceptance.",waterScenario=water,machines=world.machines.Count,actors=world.actors.Count,ticks=samples.Length,medianMs=samples[samples.Length/2],p95Ms=samples[(int)(samples.Length*.95)],simulationTicksPerSecond=samples.Length/elapsed.Elapsed.TotalSeconds,processPrivateBytes=process.PrivateMemorySize64,workingSetBytes=process.WorkingSet64,managedBytes=GC.GetTotalMemory(false)};Directory.CreateDirectory(Path.GetDirectoryName(Path.GetFullPath(args[0])));File.WriteAllText(args[0],JsonSerializer.Serialize(report,new JsonSerializerOptions{WriteIndented=true}));}}
